<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Composition with Red, Blue and Yellow (1930) — Piet Mondrian</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Archivo:wght@400;500;700;900&display=swap" rel="stylesheet">
<style>
  :root{
    --red:#dd0100; --blue:#225095; --yellow:#f9d01e;
    --black:#0d0d0d; --white:#f4f2ee; --grey:#8a8a8a;
    --line:14px;
  }
  *{box-sizing:border-box;margin:0;padding:0}
  html{scroll-behavior:smooth}
  body{
    background:var(--white);
    color:var(--black);
    font-family:'Archivo',Helvetica,Arial,sans-serif;
    line-height:1.5;
  }

  /* ---------- hero: the painting itself ---------- */
  .hero{
    min-height:100vh;
    display:grid;
    grid-template-columns:1fr 1.15fr 1fr;
    grid-template-rows:auto 1fr 1fr auto;
    gap:var(--line);
    background:var(--black);
    padding:var(--line);
  }
  .hero > *{background:var(--white);padding:2.5rem}
  .block-red{grid-column:3;grid-row:2/4;background:var(--red);color:#fff}
  .block-blue{grid-column:1;grid-row:3;align-self:end;background:var(--blue);color:#fff}
  .block-yellow{grid-column:3;grid-row:4;background:var(--yellow)}
  .hero-head{grid-column:1/3;grid-row:1;display:flex;flex-direction:column;justify-content:space-between;gap:1rem}
  .kicker{font-weight:700;letter-spacing:.35em;text-transform:uppercase;font-size:.72rem}
  h1{
    font-weight:900;
    font-size:clamp(2.2rem,6vw,4.5rem);
    line-height:1.02;
    text-transform:uppercase;
    letter-spacing:-.02em;
  }
  h1 .thin{display:block;font-weight:400;font-size:clamp(1rem,2vw,1.4rem);letter-spacing:.02em;margin-top:.6rem}
  .hero-meta{font-size:.85rem;color:var(--grey)}
  .hero-meta b{color:var(--black)}

  .block-red{display:flex;flex-direction:column;justify-content:flex-end;gap:1rem}
  .block-red p{max-width:34ch;font-weight:500}
  .block-blue{display:flex;align-items:flex-end}
  .caption{font-size:.78rem;letter-spacing:.12em;text-transform:uppercase}

  /* ---------- sections ---------- */
  main{display:grid;gap:var(--line);background:var(--black)}
  section{background:var(--white);padding:clamp(2rem,6vw,5rem)}
  .num{
    display:inline-block;
    background:var(--black);color:var(--white);
    font-weight:700;font-size:.75rem;letter-spacing:.3em;
    padding:.35rem .8rem;margin-bottom:1.4rem;text-transform:uppercase;
  }
  h2{font-weight:900;text-transform:uppercase;font-size:clamp(1.5rem,3.2vw,2.4rem);margin-bottom:1.2rem;letter-spacing:-.01em}
  p{max-width:62ch}
  p + p{margin-top:1rem}
  .rule{height:var(--line);background:var(--black)}

  .facts{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:1.5rem;margin-top:2rem;max-width:none}
  .fact{border-top:4px solid var(--black);padding-top:.8rem}
  .fact dt{font-weight:700;font-size:.72rem;letter-spacing:.28em;text-transform:uppercase;color:var(--grey)}
  .fact dd{font-weight:500;font-size:1.05rem;margin-top:.3rem}

  .principles{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:var(--line);margin-top:2rem}
  .p-card{padding:1.5rem;color:#fff;font-weight:500}
  .p-card small{display:block;margin-top:.6rem;font-weight:400;opacity:.85;font-size:.85rem}
  .p-black{background:var(--black)}
  .p-red{background:var(--red)}
  .p-blue{background:var(--blue)}
  .p-yellow{background:var(--yellow);color:var(--black)}
  .p-white{background:#fff;color:var(--black);border:2px solid var(--black)}

